`timescale 1ns/1ps
// Wraps the ACTUAL ports generated by scripts/generate_fft_ip.tcl.
// FFT: 32-bit complex, forward, scale 1/1024 (10-bit schedule 10_10_10_10_10).
// IFFT: 32-bit complex input, inverse, UNNORMALIZED, 43-bit output.
// Together the scales cancel. Do not truncate IFFT to 32 bits without analysis.
module spectral_transform #(parameter INVERSE=0)(
    input wire clk, input wire rst_n,
    input wire s_valid, output wire s_ready,
    input wire signed [31:0] s_re, input wire signed [31:0] s_im,
    input wire s_last,
    output wire m_valid, input wire m_ready,
    output wire signed [42:0] m_re, output wire signed [42:0] m_im,
    output wire [9:0] m_index, output wire m_last,
    output reg fault
);
    reg configured;
    wire config_ready, data_ready;
    wire unexpected_last, missing_last, overflow;
    wire [63:0] input_data={s_im,s_re};
    assign s_ready=configured && data_ready;
    always @(posedge clk) begin
        if(!rst_n) begin configured<=0; fault<=0; end
        else begin
            if(!configured && config_ready) configured<=1;
            if(unexpected_last || missing_last || overflow) fault<=1;
        end
    end
    generate if(INVERSE) begin: inverse_core
        wire [95:0] result;
        wire [15:0] user;
        assign m_re=result[42:0];
        assign m_im=result[90:48];
        assign m_index=user[9:0];
        assign overflow=0;
        ifft1024 core(
            .aclk(clk),.aresetn(rst_n),
            .s_axis_config_tdata(8'h00),.s_axis_config_tvalid(!configured && rst_n),.s_axis_config_tready(config_ready),
            .s_axis_data_tdata(input_data),.s_axis_data_tvalid(s_valid && configured),.s_axis_data_tready(data_ready),.s_axis_data_tlast(s_last),
            .m_axis_data_tdata(result),.m_axis_data_tuser(user),.m_axis_data_tvalid(m_valid),.m_axis_data_tready(m_ready),.m_axis_data_tlast(m_last),
            .event_tlast_unexpected(unexpected_last),.event_tlast_missing(missing_last),
            .event_frame_started(),.event_status_channel_halt(),.event_data_in_channel_halt(),.event_data_out_channel_halt());
    end else begin: forward_core
        wire [63:0] result;
        wire [23:0] user;
        assign m_re={{11{result[31]}},result[31:0]};
        assign m_im={{11{result[63]}},result[63:32]};
        assign m_index=user[9:0];
        fft1024 core(
            .aclk(clk),.aresetn(rst_n),
            .s_axis_config_tdata(16'h0555),.s_axis_config_tvalid(!configured && rst_n),.s_axis_config_tready(config_ready),
            .s_axis_data_tdata(input_data),.s_axis_data_tvalid(s_valid && configured),.s_axis_data_tready(data_ready),.s_axis_data_tlast(s_last),
            .m_axis_data_tdata(result),.m_axis_data_tuser(user),.m_axis_data_tvalid(m_valid),.m_axis_data_tready(m_ready),.m_axis_data_tlast(m_last),
            .m_axis_status_tdata(),.m_axis_status_tvalid(),.m_axis_status_tready(1'b1),
            .event_tlast_unexpected(unexpected_last),.event_tlast_missing(missing_last),.event_fft_overflow(overflow),
            .event_frame_started(),.event_status_channel_halt(),.event_data_in_channel_halt(),.event_data_out_channel_halt());
    end endgenerate
endmodule
